  virtual std::any parseOrderStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("UNFILLED"), std::string("open")},
        {std::string("PARTIALLY_FILLED"), std::string("open")},
        {std::string("FULLY_FILLED"), std::string("closed")},
        {std::string("CANCELED_UNFILLED"), std::string("canceled")},
        {std::string("CANCELED_PARTIALLY_FILLED"), std::string("canceled")},
    };
    return this->safeString(statuses, status, status);
  }

  std::any parseOrder(std::any order, std::any market = std::any{}) override {
    std::any id = this->safeString(order, std::string("order_id"));
    std::any marketId = this->safeString(order, std::string("pair"));
    market = this->safeMarket(marketId, market);
    std::any timestamp = this->safeInteger(order, std::string("ordered_at"));
    std::any price = this->safeString(order, std::string("price"));
    std::any amount = this->safeString(order, std::string("start_amount"));
    std::any filled = this->safeString(order, std::string("executed_amount"));
    std::any remaining =
        this->safeString(order, std::string("remaining_amount"));
    std::any average = this->safeString(order, std::string("average_price"));
    std::any status =
        this->parseOrderStatus(this->safeString(order, std::string("status")));
    std::any type = this->safeStringLower(order, std::string("type"));
    std::any side = this->safeStringLower(order, std::string("side"));
    return this->safeOrder(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("clientOrderId"), std::any{}},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("timestamp"), timestamp},
            {std::string("lastTradeTimestamp"), std::any{}},
            {std::string("status"), status},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("type"), type},
            {std::string("timeInForce"), std::any{}},
            {std::string("postOnly"), std::any{}},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("triggerPrice"), std::any{}},
            {std::string("cost"), std::any{}},
            {std::string("average"), average},
            {std::string("amount"), amount},
            {std::string("filled"), filled},
            {std::string("remaining"), remaining},
            {std::string("trades"), std::any{}},
            {std::string("fee"), std::any{}},
            {std::string("info"), order},
        },
        market);
  }

  /**
   * @method
   * @name bitbank#createOrder
   * @description create a trade order
   * @see
   * https://github.com/bitbankinc/bitbank-api-docs/blob/38d6d7c6f486c793872fd4b4087a0d090a04cd0a/rest-api.md#create-new-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any request = ccxt::dict{
                            {std::string("pair"),
                             ::getValue(market, std::string("id"))},
                            {std::string("amount"),
                             this->amountToPrecision(symbol, amount)},
                            {std::string("side"), side},
                            {std::string("type"), type},
                        };
                        if (isTrue(isEqual(type, std::string("limit")))) {
                          ::setValue(request, std::string("price"),
                                     this->priceToPrecision(symbol, price));
                        }
                        std::any response =
                            awaitValue(this->privatePostUserSpotOrder(
                                this->extend(request, params)));
                        std::any data =
                            this->safeDict(response, std::string("data"));
                        return this->parseOrder(data, market);
                      })
        .share();
  }

